#pragma once
namespace SplatVerification {
inline void RunRadixIntegrationTests(Suite& suite){
    suite.Test("RADIX runtime JSON strict controls defaults and GPU limit",[]{
        auto dir=Directory("radix-config");std::string error;auto parse=[&](const std::string& fields,FSplatLODRuntimeOptions& out){auto p=dir/"runtime.json";std::ofstream f(p);f<<'{'<<fields<<'}';f.close();return FSplatLODRuntimeOptions::LoadConfig(p.string(),out,error);};
        FSplatLODRuntimeOptions o;Require(parse("",o)&&o.radixSortBlocksPerWorkgroup==32&&o.radixSortPhaseTiming,"radix defaults");
        for(unsigned b:{4u,8u,16u,32u}){Require(parse("\"radixSortBlocksPerWorkgroup\":"+std::to_string(b)+",\"radixSortPhaseTiming\":false",o),error);Require(o.radixSortBlocksPerWorkgroup==b&&!o.radixSortPhaseTiming,"strict config roundtrip");o.sortCapacity=65535u*256u*b;Require(o.Validate(error),error);++o.sortCapacity;Require(!o.Validate(error),"oversized radix dispatch capacity accepted");}
        for(const char* bad:{"0","-1","3","5","33","4.5","true","\"4\"","null","4294967296"}){auto old=o;Require(!parse(std::string("\"radixSortBlocksPerWorkgroup\":")+bad,o),std::string("invalid blocks accepted: ")+bad);Require(o.radixSortBlocksPerWorkgroup==old.radixSortBlocksPerWorkgroup,"parse failure mutated output");}
        for(const char* bad:{"0","1","\"false\"","null"})Require(!parse(std::string("\"radixSortPhaseTiming\":")+bad,o),"nonbool phase control accepted");
    });
    for(bool timing:{false,true})for(bool complete:{false,true})suite.Test("RADIX recorder phase availability timing="+std::to_string(timing)+" complete="+std::to_string(complete),[timing,complete]{
        FSplatLODRuntimeOptions o;o.benchmark=true;o.sequencePath="radix-recorder-bookkeeping";o.outputDirectory=Directory("radix-recorder").string();FSplatLODBenchmark recorder;std::string error;Require(recorder.Begin(o,{},error),error);FSplatLODBenchmarkFrame row;row.frame=87;row.sampled=true;row.pipeline.radixPhaseTimingEnabled=timing;row.pipeline.radixSortBlocksPerWorkgroupRequested=row.pipeline.radixSortBlocksPerWorkgroupEffective=8;row.pipeline.radixKeysBytes=1234;row.pipeline.radixValuesBytes=5678;row.pipeline.radixHistogramBytes=8192;row.pipeline.countSamples={{87,1,false}};for(const char* stage:{"Pipeline","Preprocess","Scan","AssignKeys","RadixSort","TileBounds","Render"})row.pipeline.timestampSamples.push_back({87,stage,1});if(complete)for(const char* stage:{"RadixHistogram","RadixOffsets","RadixScatter"})row.pipeline.timestampSamples.push_back({87,stage,.25});Require(recorder.Record(row,error),error);bool ok=recorder.Finish(true,"pure recorder events; not hardware evidence",error);Require(ok==(!timing||complete),"phase availability changed verification status");auto bytes=Read(fs::path(o.outputDirectory)/"frames.csv");std::string text(bytes.begin(),bytes.end());Require(text.find("radix_histogram_ms")!=std::string::npos&&text.find(",8,8,")!=std::string::npos&&text.find(",1234,5678,8192,")!=std::string::npos,"radix telemetry columns or allocation values absent");if(timing&&!complete)Require(text.find(",8,8,,,,")!=std::string::npos,"unavailable child times replaced with zero");
    });
}
}
